{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \"Asia/Kolkata\"; create or replace table snitch_db.maplemonk.cogs_otb_v2_check as WITH default_inwards_cogs AS ( select TO_DATE(month, \'DD-MM-YYYY\') AS month, l_1 l1,cat,default_inwards_cogs from snitch_db.maplemonk.inwards_plan_default_sheet1 ) , meta_sku_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, MAX(COALESCE(a.cogs, 0)) AS sku_cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ), l1cat_avg_cogs AS ( SELECT l1_category, category, AVG(NULLIF(sku_cogs, 0)) AS avg_cogs FROM meta_sku_map GROUP BY 1, 2 ), sales_pred_qty AS ( WITH actual_targets AS ( SELECT category, l_1_category AS l1_category, DATE_TRUNC(\'MONTH\', TO_DATE(month, \'DD/MM/YYYY\')) AS month, SUM(COALESCE(qty, 0)) AS qty FROM snitch_db.maplemonk.sales_pred_channel_targets_set GROUP BY 1, 2, 3 ), actual_months AS ( SELECT DISTINCT month FROM actual_targets ), future_targets_unpivot AS ( SELECT l_1 AS l1_category, cat AS category, month_name, qty FROM snitch_db.maplemonk.sales_pred_demand_pred UNPIVOT ( qty FOR month_name IN ( MAY, JUNE, JULY, AUG, SEPT, OCT, NOV, DEC, JAN, FEB ) ) ), future_targets AS ( SELECT category, l1_category, CASE UPPER(month_name) WHEN \'MAY\' THEN DATE \'2026-05-01\' WHEN \'JUNE\' THEN DATE \'2026-06-01\' WHEN \'JULY\' THEN DATE \'2026-07-01\' WHEN \'AUG\' THEN DATE \'2026-08-01\' WHEN \'SEPT\' THEN DATE \'2026-09-01\' WHEN \'OCT\' THEN DATE \'2026-10-01\' WHEN \'NOV\' THEN DATE \'2026-11-01\' WHEN \'DEC\' THEN DATE \'2026-12-01\' WHEN \'JAN\' THEN DATE \'2027-01-01\' WHEN \'FEB\' THEN DATE \'2027-02-01\' END AS month, SUM(COALESCE(qty, 0)) AS qty FROM future_targets_unpivot GROUP BY 1, 2, 3 ), future_targets_filtered AS ( SELECT f.* FROM future_targets f LEFT JOIN actual_months a ON f.month = a.month WHERE a.month IS NULL ) SELECT category, l1_category, month, qty FROM actual_targets UNION ALL SELECT category, l1_category, month, qty FROM future_targets_filtered ), sales_pred_cogs AS ( SELECT s.month, s.l1_category AS l1, s.category AS cat, SUM(COALESCE(s.qty, 0) * COALESCE(a.avg_cogs, 0)) AS sales_pred_cogs FROM sales_pred_qty s LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(s.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(s.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), inwards_qty AS ( WITH base AS ( SELECT final_sku AS sku, COALESCE(qty, 0) AS qty, UPPER( REGEXP_SUBSTR( remarks_final, \'March|April|May|June|July|August|September|October|November|December|January|February\', 1, 1, \'i\' ) ) AS month_name FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks WHERE final_sku IS NOT NULL ), non_march AS ( SELECT sku, CASE WHEN month_name = \'APRIL\' THEN DATE \'2026-04-01\' WHEN month_name = \'MAY\' THEN DATE \'2026-05-01\' WHEN month_name = \'JUNE\' THEN DATE \'2026-06-01\' WHEN month_name = \'JULY\' THEN DATE \'2026-07-01\' WHEN month_name = \'AUGUST\' THEN DATE \'2026-08-01\' WHEN month_name = \'SEPTEMBER\' THEN DATE \'2026-09-01\' WHEN month_name = \'OCTOBER\' THEN DATE \'2026-10-01\' WHEN month_name = \'NOVEMBER\' THEN DATE \'2026-11-01\' WHEN month_name = \'DECEMBER\' THEN DATE \'2026-12-01\' WHEN month_name = \'JANUARY\' THEN DATE \'2027-01-01\' WHEN month_name = \'FEBRUARY\' THEN DATE \'2027-02-01\' END AS month, qty FROM base WHERE month_name IS NOT NULL AND month_name <> \'MARCH\' ), march_data AS ( SELECT sku, DATE \'2026-03-01\' AS month, COALESCE(qty, 0) AS qty FROM snitch_db.maplemonk.march_only_inwards_list_mar_only_inwards_list___qty ) SELECT sku, month, qty FROM non_march UNION ALL SELECT sku, month, qty FROM march_data ), inwards_cogs AS ( SELECT i.month, m.l1_category AS l1, m.category AS cat, SUM( COALESCE(i.qty, 0) * COALESCE( NULLIF(m.sku_cogs, 0), a.avg_cogs, 0 ) ) AS inwards_target_cogs FROM inwards_qty i LEFT JOIN meta_sku_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(i.sku, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(i.sku, \' \', \'\'), \'-.*$\', \'\') ) ) LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), inwards_plan_presence AS ( SELECT i.month, m.l1_category AS l1, m.category AS cat, COUNT(*) AS plan_row_count FROM inwards_qty i LEFT JOIN meta_sku_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(i.sku, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(i.sku, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(i.sku, \' \', \'\'), \'-.*$\', \'\') ) ) GROUP BY 1, 2, 3 ), actual_inwards_qty AS ( SELECT DATE_TRUNC(\'MONTH\', \"PUTAWAY_UPDATED\"::DATE) AS month, UPPER( IFF( UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, SUM(COALESCE(\"PUTAWAY_COMPLETED_QUANTITY\", 0)) AS qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= DATE \'2026-03-01\' AND LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1, 2 HAVING SUM(COALESCE(\"PUTAWAY_COMPLETED_QUANTITY\", 0)) >= 30 ), actual_inwards_cogs AS ( SELECT q.month, m.l1_category AS l1, m.category AS cat, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS actual_inwards_cogs FROM actual_inwards_qty q LEFT JOIN meta_sku_map m ON q.sku_group_clean = m.sku_group_clean LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), return_inwards_qty AS ( SELECT DATE_TRUNC(\'MONTH\', \"PUTAWAY_UPDATED\"::DATE) AS month, UPPER( IFF( UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(\"Item Type skuCode\", \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(\"Item Type skuCode\", \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, CASE WHEN UPPER(TRIM(FINAL_TYPE)) = \'STORE RETURN INWARD\' THEN \'STORE_RETURN_INWARDS\' WHEN UPPER(TRIM(FINAL_TYPE)) = \'B2C RETURN INWARD\' THEN \'B2C_RETURN_INWARDS\' END AS return_type, SUM(COALESCE(\"PUTAWAY_COMPLETED_QUANTITY\", 0)) AS qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= DATE \'2026-03-01\' AND UPPER(TRIM(FINAL_TYPE)) IN (\'STORE RETURN INWARD\', \'B2C RETURN INWARD\') GROUP BY 1, 2, 3 ), return_inwards_cogs AS ( SELECT q.month, m.l1_category AS l1, m.category AS cat, SUM( CASE WHEN q.return_type = \'STORE_RETURN_INWARDS\' THEN COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ELSE 0 END ) AS store_return_inwards_cogs, SUM( CASE WHEN q.return_type = \'B2C_RETURN_INWARDS\' THEN COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ELSE 0 END ) AS b2c_return_inwards_cogs, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS return_inwards_cogs FROM return_inwards_qty q LEFT JOIN meta_sku_map m ON q.sku_group_clean = m.sku_group_clean LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), actual_sales_qty AS ( SELECT DATE_TRUNC(\'MONTH\', date::DATE) AS month, UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, SUM(COALESCE(gross_quantity::INT, 0)) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories WHERE date::DATE >= DATE \'2026-03-01\' GROUP BY 1, 2 ), actual_sales_cogs AS ( SELECT q.month, m.l1_category AS l1, m.category AS cat, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS actual_sales_cogs FROM actual_sales_qty q LEFT JOIN meta_sku_map m ON q.sku_group_clean = m.sku_group_clean LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2, 3 ), last_30d_sales_qty AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, sku_group, SUM(COALESCE(gross_quantity::INT, 0)) AS qty FROM snitch_db.maplemonk.horizontal_sales_categories WHERE date::DATE >= CURRENT_DATE - 30 AND date::DATE < CURRENT_DATE GROUP BY 1,2 ), last_30d_sales_cogs AS ( SELECT sku_group, sku_group_clean, m.l1_category AS l1, m.category AS cat, COALESCE(NULLIF(m.sku_cogs, 0), 0) cogs, SUM( COALESCE(q.qty, 0) * COALESCE(NULLIF(m.sku_cogs, 0), a.avg_cogs, 0) ) AS last_30d_sales_cogs, SUM( COALESCE(q.qty, 0)) qty FROM last_30d_sales_qty q LEFT JOIN meta_sku_map m using(sku_group_clean) LEFT JOIN l1cat_avg_cogs a ON UPPER(TRIM(m.l1_category)) = UPPER(TRIM(a.l1_category)) AND UPPER(TRIM(m.category)) = UPPER(TRIM(a.category)) GROUP BY 1, 2,3,4,5 ) select * from last_30d_sales_cogs;",
                    "transaction": true
                }
            ) }}
